    let ret = sig_verify(
        session,
        pub_handle,
        msg.as_slice(),
        signature.as_slice(),
        &mechanism,
    );
    assert_eq!(ret, CKR_OK);
    assert_eq!(check_validation(session, 1), true);

    let out = ret_or_panic!(sig_gen(
        session,
        priv_handle,
        msg.as_slice(),
        &mechanism
    ));
    assert_eq!(out, signature);
    assert_eq!(check_validation(session, 1), true);

    /* re-test but using the C_VerifySignature API */
    let ret = sig_verifysig(
        session,
        pub_handle,
        msg.as_slice(),
        signature.as_slice(),
        &mechanism,
    );
    assert_eq!(ret, CKR_OK);
    assert_eq!(check_validation(session, 1), true);

